refused_program.body:
git fetch "{upstream_remote}"
git merge --no-ff --no-edit "{upstream_remote}/{upstream_branch}" || true

if git ls-files -u -- deps.lock | grep -q .; then
  base=$(git merge-base HEAD "{upstream_remote}/{upstream_branch}")
  tmp=$(mktemp)
  added=$(mktemp)
  removed=$(mktemp)
  git show "{upstream_remote}/{upstream_branch}:deps.lock" > "$tmp"
  git diff --no-color -U0 "$base" HEAD -- deps.lock \
    | sed -n 's/^+\([^+].*\)$/\1/p' \
    | grep -E '^[[:space:]]*"[^"]+"[[:space:]]*,?[[:space:]]*$' > "$added" || true
  git diff --no-color -U0 "$base" HEAD -- deps.lock \
    | sed -n 's/^-\([^-].*\)$/\1/p' \
    | grep -E '^[[:space:]]*"[^"]+"[[:space:]]*,?[[:space:]]*$' > "$removed" || true
  awk -v added_file="$added" -v removed_file="$removed" '
  BEGIN {
    while ((getline line < removed_file) > 0) removed[line] = 1
    while ((getline line < added_file) > 0) { n++; additions[n] = line; is_added[line] = 1 }
  }
  {
    if ($0 in removed) next
    if (($0 in is_added) && ($0 in printed)) next
    if (!inserted && $0 ~ /^[[:space:]]*\][[:space:]]*$/) {
      for (i = 1; i <= n; i++) {
        if (!(additions[i] in printed)) {
          print additions[i]
          printed[additions[i]] = 1
        }
      }
      inserted = 1
    }
    print $0
    printed[$0] = 1
    if ($0 ~ /^[[:space:]]*packages[[:space:]]*=[[:space:]]*\[[[:space:]]*$/) {
      for (i = 1; i <= n; i++) {
        if (!(additions[i] in printed)) {
          print additions[i]
          printed[additions[i]] = 1
        }
      }
      inserted = 1
    }
  }
  ' "$tmp" > "$tmp.new"
  mv "$tmp.new" deps.lock
  rm -f "$tmp" "$added" "$removed"
  git add deps.lock
  git commit --no-edit
fi
